CREATE TABLE public.site_appearance (id text PRIMARY KEY DEFAULT 'main' CHECK (id = 'main'), title text NOT NULL DEFAULT 'KASIGARA TV', tagline text NOT NULL DEFAULT 'Mpira · TV · Burudani', description text NOT NULL DEFAULT 'Mechi na burudani kwenye simu yako. Sakinisha app kwanza, kisha fungua kupitia ikoni yake kuona chaneli na kuingia kwenye akaunti.', button_label text NOT NULL DEFAULT 'Sakinisha app', image_url text, logo_url text, theme text NOT NULL DEFAULT 'green' CHECK (theme IN ('green','red','cyan')), CHECK (char_length(title) BETWEEN 2 AND 50), CHECK (char_length(tagline) BETWEEN 1 AND 100), CHECK (char_length(description) BETWEEN 1 AND 500), CHECK (char_length(button_label) BETWEEN 2 AND 40)); GRANT SELECT ON public.site_appearance TO anon; GRANT SELECT, INSERT, UPDATE ON public.site_appearance TO authenticated; GRANT ALL ON public.site_appearance TO service_role; ALTER TABLE public.site_appearance ENABLE ROW LEVEL SECURITY; CREATE POLICY appearance_public_read ON public.site_appearance FOR SELECT TO anon, authenticated USING (true); CREATE POLICY appearance_admin_insert ON public.site_appearance FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin')); CREATE POLICY appearance_admin_update ON public.site_appearance FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));